/**
 * iPin Masonry  v1.0.0
 * Column-based cascading grid layout engine.
 *
 * API surface matches Masonry v4 so existing call-sites work unchanged:
 *
 *   $(grid).masonry({ itemSelector, columnWidth, gutter, fitWidth })
 *   $(grid).masonry('appended', $newItems, true)
 *   $(grid).masonry('layout')
 *   $(grid).masonry('destroy')
 *
 * Algorithm:
 *   Items are placed into the shortest column — classic "bin-packing"
 *   approach. The container width is auto-calculated; if fitWidth is
 *   true the container is shrunk to the total occupied column width so
 *   it can be centred with margin:auto.
 *
 * Written from scratch for iPin Modern.
 * No external dependencies beyond jQuery.
 */
;(function ($) {
  'use strict';

  // ─────────────────────────────────────────────────────
  //  Internal state storage — keyed by element
  // ─────────────────────────────────────────────────────
  var instances = [];  // [{ el, options, colHeights, colWidth }]

  function getInstance(el) {
    for (var i = 0; i < instances.length; i++) {
      if (instances[i].el === el) return instances[i];
    }
    return null;
  }

  function setInstance(el, data) {
    var existing = getInstance(el);
    if (existing) {
      $.extend(existing, data);
    } else {
      instances.push($.extend({ el: el }, data));
    }
  }

  function removeInstance(el) {
    for (var i = 0; i < instances.length; i++) {
      if (instances[i].el === el) {
        instances.splice(i, 1);
        return;
      }
    }
  }


  // ─────────────────────────────────────────────────────
  //  Layout engine
  // ─────────────────────────────────────────────────────

  /**
   * Measure the column width.
   *
   * If `columnWidth` is a string selector, the width of the first
   * matching element is used.  If it's a number it's used directly.
   * Falls back to the width of the first item.
   *
   * @param  {Element}        container
   * @param  {string|number}  colWidthOpt  — option value from settings
   * @param  {string}         itemSelector
   * @returns {number}
   */
  function measureColWidth(container, colWidthOpt, itemSelector) {
    if (typeof colWidthOpt === 'number') {
      return colWidthOpt;
    }
    if (typeof colWidthOpt === 'string') {
      var sizer = container.querySelector(colWidthOpt);
      if (sizer) return sizer.getBoundingClientRect().width;
    }
    // Fall back to first item
    var first = container.querySelector(itemSelector);
    return first ? first.getBoundingClientRect().width : 0;
  }

  /**
   * Run a full layout pass on `container` using its stored instance data.
   *
   * @param {Element} container
   */
  function layout(container) {
    var inst = getInstance(container);
    if (!inst) return;

    var opts         = inst.options;
    var gutter       = opts.gutter   || 0;
    var itemSel      = opts.itemSelector || '.thumb';
    var colWidth     = measureColWidth(container, opts.columnWidth, itemSel);

    if (!colWidth) return;  // not yet in DOM / zero-width — bail

    // How many columns fit?
    var containerWidth = container.getBoundingClientRect().width;
    var numCols = Math.max(1, Math.floor(
      (containerWidth + gutter) / (colWidth + gutter)
    ));

    // Column height tracker — one entry per column, starts at 0.
    var colHeights = new Array(numCols);
    for (var c = 0; c < numCols; c++) colHeights[c] = 0;

    // Left offset of each column.
    var colLeft = new Array(numCols);
    for (var c2 = 0; c2 < numCols; c2++) {
      colLeft[c2] = c2 * (colWidth + gutter);
    }

    // Position items.
    var items = container.querySelectorAll(itemSel);
    for (var i = 0; i < items.length; i++) {
      var item = items[i];
      var itemStyle = item.style;

      // Ensure items are absolutely positioned.
      itemStyle.position = 'absolute';
      itemStyle.width    = colWidth + 'px';

      // Find shortest column.
      var minH   = colHeights[0];
      var minCol = 0;
      for (var k = 1; k < numCols; k++) {
        if (colHeights[k] < minH) {
          minH   = colHeights[k];
          minCol = k;
        }
      }

      // Place item.
      itemStyle.left = colLeft[minCol] + 'px';
      itemStyle.top  = colHeights[minCol] + 'px';

      // Advance that column's height.
      colHeights[minCol] += item.getBoundingClientRect().height + gutter;
    }

    // Size the container.
    var maxH = Math.max.apply(null, colHeights);
    container.style.position = 'relative';
    container.style.height   = Math.max(0, maxH - gutter) + 'px';

    if (opts.fitWidth) {
      // Shrink container to used columns so it can be centred.
      var usedCols = Math.min(numCols, items.length);
      container.style.width = (usedCols * (colWidth + gutter) - gutter) + 'px';
    }

    // Persist column heights for incremental appended() calls.
    inst.colHeights = colHeights;
    inst.colWidth   = colWidth;
    inst.numCols    = numCols;
    inst.colLeft    = colLeft;
  }


  // ─────────────────────────────────────────────────────
  //  Append new items without full re-layout
  // ─────────────────────────────────────────────────────

  /**
   * Place newly appended items into the existing column structure,
   * then extend the container height.
   *
   * @param {Element}   container
   * @param {jQuery}    $newItems
   */
  function appended(container, $newItems) {
    var inst = getInstance(container);
    if (!inst || !inst.colHeights) {
      // No previous layout — do a full pass.
      layout(container);
      return;
    }

    var opts       = inst.options;
    var gutter     = opts.gutter || 0;
    var colHeights = inst.colHeights;
    var colWidth   = inst.colWidth;
    var colLeft    = inst.colLeft;

    $newItems.each(function () {
      var item      = this;
      var itemStyle = item.style;

      itemStyle.position = 'absolute';
      itemStyle.width    = colWidth + 'px';

      // Shortest column.
      var minH   = colHeights[0];
      var minCol = 0;
      for (var k = 1; k < colHeights.length; k++) {
        if (colHeights[k] < minH) {
          minH   = colHeights[k];
          minCol = k;
        }
      }

      itemStyle.left = colLeft[minCol] + 'px';
      itemStyle.top  = colHeights[minCol] + 'px';

      colHeights[minCol] += item.getBoundingClientRect().height + gutter;
    });

    // Expand container height.
    var maxH = Math.max.apply(null, colHeights);
    container.style.height = Math.max(0, maxH - gutter) + 'px';
  }


  // ─────────────────────────────────────────────────────
  //  Reflow on resize (debounced)
  // ─────────────────────────────────────────────────────

  var resizeTimer = null;

  $(window).on('resize.ipinMasonry', function () {
    clearTimeout(resizeTimer);
    resizeTimer = setTimeout(function () {
      for (var i = 0; i < instances.length; i++) {
        layout(instances[i].el);
      }
    }, 120);
  });


  // ─────────────────────────────────────────────────────
  //  jQuery plugin interface
  // ─────────────────────────────────────────────────────

  /**
   * $.fn.masonry( options )           — initialise / re-configure
   * $.fn.masonry( 'layout' )          — re-run layout
   * $.fn.masonry( 'appended', $els )  — add new items
   * $.fn.masonry( 'destroy' )         — remove plugin, restore styles
   */
  $.fn.masonry = function (optionsOrMethod, $newItems) {

    // ── Method call ────────────────────────────────────
    if (typeof optionsOrMethod === 'string') {
      var method = optionsOrMethod;

      return this.each(function () {
        var el   = this;
        var inst = getInstance(el);

        if (method === 'layout') {
          layout(el);

        } else if (method === 'appended' && $newItems) {
          appended(el, $newItems);

        } else if (method === 'destroy') {
          if (!inst) return;
          // Reset container styles.
          el.style.position = '';
          el.style.height   = '';
          el.style.width    = '';
          // Reset item styles.
          var itemSel = inst.options.itemSelector || '.thumb';
          var items   = el.querySelectorAll(itemSel);
          for (var i = 0; i < items.length; i++) {
            items[i].style.position = '';
            items[i].style.left     = '';
            items[i].style.top      = '';
            items[i].style.width    = '';
          }
          removeInstance(el);
        }
      });
    }

    // ── Initialisation ─────────────────────────────────
    var options = $.extend({
      itemSelector: '.thumb',
      columnWidth:  '.thumb',
      gutter:       12,
      fitWidth:     true,
    }, optionsOrMethod);

    return this.each(function () {
      setInstance(this, { options: options });
      layout(this);
    });
  };

}(jQuery));
